fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // Requires: The input vector `a` must not be empty.
    // Ensures: The output is a vector of vectors of strings, where each inner vector contains
    //          the lines split from the corresponding string in `a`.
    //          If `keepends` is false, the lines will not include trailing newline characters.
    //          Each inner vector will contain at least one string (an empty string if the original string was empty).
    // Invariant: For each string `s` in `a`, the resulting vector of strings must be non-empty.
    // Decreases: The length of the input vector `a` decreases with each iteration.
    let result: Vec<Vec<String>> = a.into_iter()
        .map(|s| {
            // Split the string into lines based on line endings
            let mut lines: Vec<String> = if keepends {
                s.split('\n').map(|line| line.to_string()).collect()
            } else {
                s.split('\n')
                    .map(|line| line.trim_end().to_string()) // Trim the end if not keeping ends
                    .collect()
            };

            // Ensure that each inner list is non-empty
            // This should not happen as per the problem statement
            if lines.is_empty() {
                lines.push(String::new());
            }

            // Assert that the inner vector is non-empty
            assert!(!lines.is_empty());

            lines
        })
        .collect();

    // Ensure that the result is a vector of non-empty vectors
    assert!(result.iter().all(|v| !v.is_empty()));

    result
}

fn main() {
    let input = vec![
        String::from("Hello\nWorld"),
        String::from("Rust\nProgramming\nLanguage"),
    ];
    
    let result = splitlines(input, false);
    for lines in result {
        println!("{:?}", lines);
    }
}